mapper.select:
select a.*, pa.name attrName, pa.type attrType, pa.remark attrRemark from iot_model_api_config a
    left join iot_protocol_attr pa on a.attr_field=pa.field and a.api_code=#{apiCode}
where api_code=#{apiCode} and a.direction='UP' order by sort

select a.*, pa.name attrName, pa.type attrType, pa.remark attrRemark from iot_model_api_config a
    left join iot_protocol_attr pa on a.attr_field=pa.field and a.api_code=#{apiCode}
where api_code=#{apiCode} and a.direction='DOWN' order by sort
